import{_ as r,C as d,o as e,c as i,a5 as a,E as l}from"./chunks/framework.B5tqjWbr.js";const m=JSON.parse('{"title":"路径12: PMSM控制策略仿真","description":"","frontmatter":{"date":"2026-06-04T00:00:00.000Z","section":"电机控制","chapter":"practice","chapterTitle":"工程实践","chapterOrder":20,"category":"工程实践","source":"motor","visibility":"public","title":"路径12: PMSM控制策略仿真","tags":["motor-control"],"status":"learning","summary":"> 来源：手把手电机控制仿真 Part 1-6 + DTC | 前置：路径11站1-5 | 难度：★★★~★★★★★","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/practice/PRACTICE-12-PMSM-Simulation.md","filePath":"content/motor/practice/PRACTICE-12-PMSM-Simulation.md","lastUpdated":null}'),n={name:"content/motor/practice/PRACTICE-12-PMSM-Simulation.md"};function s(h,t,c,P,A,u){const o=d("MermaidDiagram");return e(),i("div",null,[t[0]||(t[0]=a('<h1 id="路径12-pmsm控制策略仿真" tabindex="-1">路径12: PMSM控制策略仿真 <a class="header-anchor" href="#路径12-pmsm控制策略仿真" aria-label="Permalink to &quot;路径12: PMSM控制策略仿真&quot;">​</a></h1><blockquote><p>来源：手把手电机控制仿真 Part 1-6 + DTC | 前置：路径11站1-5 | 难度：★★★~★★★★★</p></blockquote><h2 id="_1-路径概述" tabindex="-1">1. 路径概述 <a class="header-anchor" href="#_1-路径概述" aria-label="Permalink to &quot;1. 路径概述&quot;">​</a></h2><p>从基础双闭环到高级MTPA+弱磁的PMSM控制策略系统性仿真验证。适合已完成路径11(FOC仿真到固件)的学习者，通过递进式专题深化对PMSM控制策略的理解。</p><p><strong>前置知识：</strong> 路径11站1-5（FOC仿真基础） <strong>学习目标：</strong> 系统性掌握PMSM从基础双闭环到高级MTPA+弱磁的控制策略，理解各策略的适用场景</p><h2 id="_2-学习路径图" tabindex="-1">2. 学习路径图 <a class="header-anchor" href="#_2-学习路径图" aria-label="Permalink to &quot;2. 学习路径图&quot;">​</a></h2>',6)),l(o,{code:"graph%20LR%0A%20%20%20%20A%5B%E7%AB%991%3A%20%E5%8F%8C%E9%97%AD%E7%8E%AFFOC%5D%20--%3E%20B%5B%E7%AB%992%3A%20%E7%94%B5%E6%B5%81%E7%8E%AF%E5%8F%82%E6%95%B0%5D%0A%20%20%20%20A%20--%3E%20C%5B%E7%AB%993%3A%20%E8%BD%AC%E9%80%9F%E7%8E%AF%E5%8F%82%E6%95%B0%5D%0A%20%20%20%20B%20--%3E%20D%5B%E7%AB%994%3A%20%E6%A8%A1%E7%B3%8API%5D%0A%20%20%20%20C%20--%3E%20D%0A%20%20%20%20D%20--%3E%20E%5B%E7%AB%995%3A%20%E4%B8%89%E9%97%AD%E7%8E%AF%E4%BD%8D%E7%BD%AE%E6%8E%A7%E5%88%B6%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20E%20--%3E%20F%5B%E7%AB%996%3A%20MTPA%E4%B8%93%E9%A2%98%5D%0A%20%20%20%20F%20--%3E%20G%5B%E7%AB%997%3A%20MTPA%2B%E5%BC%B1%E7%A3%81%E7%BB%BC%E5%90%88%5D%0A"}),t[1]||(t[1]=a('<h2 id="_3-站点详情表" tabindex="-1">3. 站点详情表 <a class="header-anchor" href="#_3-站点详情表" aria-label="Permalink to &quot;3. 站点详情表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>站号</th><th>主题</th><th>资源引用</th><th>交叉引用KB模块</th><th>难度</th><th>预计学习时间</th></tr></thead><tbody><tr><td>站1</td><td>双闭环FOC控制系统</td><td>📂 <code>第1部分.zip</code>.zip) 🔑解压密码:chenshamotor</td><td>ALG-05(有感FOC)</td><td>★★★☆☆</td><td>4-5小时</td></tr><tr><td>站2</td><td>电流环参数设计</td><td>📂 <code>B站电流环.zip</code> 🔑chenshamotor</td><td>ALG-03(PI调节器)</td><td>★★★☆☆</td><td>3-4小时</td></tr><tr><td>站3</td><td>转速环参数设计</td><td>📂 <code>B站转速环.zip</code> 🔑chenshamotor</td><td>ALG-12(速度环)</td><td>★★★☆☆</td><td>3-4小时</td></tr><tr><td>站4</td><td>模糊PI双闭环控制</td><td>📂 <code>第2部分.zip</code> 🔑chenshamotor</td><td>CT-15(PID优化策略)</td><td>★★★★☆</td><td>4-5小时</td></tr><tr><td>站5</td><td>三闭环位置控制</td><td>📂 <code>第3部分.zip</code>.zip) 🔑chenshamotor</td><td>CT-14(三环级联PID), ALG-12(速度环)</td><td>★★★★☆</td><td>4-5小时</td></tr><tr><td>站6</td><td>MTPA专题</td><td>📂 <code>第4部分.zip</code>.zip) 🔑chenshamotor</td><td>ALG-11(MTPA), ADV-ALG-05(弱磁MTPA深度)</td><td>★★★★☆</td><td>5-6小时</td></tr><tr><td>站7</td><td>MTPA+弱磁综合策略</td><td>📂 <code>第5部分.zip</code>.zip) + 📂 <code>第6部分.zip</code> 🔑chenshamotor</td><td>ALG-11(MTPA与弱磁)</td><td>★★★★★</td><td>6-8小时</td></tr></tbody></table><h2 id="_4-各站详细说明" tabindex="-1">4. 各站详细说明 <a class="header-anchor" href="#_4-各站详细说明" aria-label="Permalink to &quot;4. 各站详细说明&quot;">​</a></h2><h3 id="站1-双闭环foc控制系统" tabindex="-1">站1: 双闭环FOC控制系统 <a class="header-anchor" href="#站1-双闭环foc控制系统" aria-label="Permalink to &quot;站1: 双闭环FOC控制系统&quot;">​</a></h3><ul><li><strong>核心要点：</strong> PMSM电流环+速度环FOC仿真搭建，id=0控制策略</li><li><strong>资源使用方法：</strong> 解压zip后按README顺序操作，先运行参数脚本再打开Simulink模型</li><li><strong>学习建议：</strong> 如果已完成路径11站3和站5，本站可快速浏览，重点对比两种仿真实现的差异</li></ul><h3 id="站2-电流环参数设计" tabindex="-1">站2: 电流环参数设计 <a class="header-anchor" href="#站2-电流环参数设计" aria-label="Permalink to &quot;站2: 电流环参数设计&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 电流环PI参数理论计算与仿真验证，带宽设计方法</li><li><strong>资源使用方法：</strong> 解压后运行MATLAB脚本，对照B站视频教程理解参数设计过程</li><li><strong>学习建议：</strong> 与路径11站3形成互补——路径11侧重公式推导，本站侧重整定实操</li></ul><h3 id="站3-转速环参数设计" tabindex="-1">站3: 转速环参数设计 <a class="header-anchor" href="#站3-转速环参数设计" aria-label="Permalink to &quot;站3: 转速环参数设计&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 速度环PI参数设计，带宽分配原则（电流环:速度环 ≈ 10:1）</li><li><strong>资源使用方法：</strong> 解压后运行脚本，观察不同参数下的速度响应</li><li><strong>学习建议：</strong> 对照KB模块ALG-12(速度环与转矩观测器)的理论分析</li></ul><h3 id="站4-模糊pi双闭环控制" tabindex="-1">站4: 模糊PI双闭环控制 <a class="header-anchor" href="#站4-模糊pi双闭环控制" aria-label="Permalink to &quot;站4: 模糊PI双闭环控制&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 模糊推理替代传统PI整定，隶属度函数设计，规则库建立</li><li><strong>资源使用方法：</strong> 解压后对比传统PI与模糊PI的仿真波形</li><li><strong>学习建议：</strong> 模糊PI是传统PI的智能优化版本，理解其与站2/3传统PI的差异和适用场景</li></ul><h3 id="站5-三闭环位置控制" tabindex="-1">站5: 三闭环位置控制 <a class="header-anchor" href="#站5-三闭环位置控制" aria-label="Permalink to &quot;站5: 三闭环位置控制&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 电流环+速度环+位置环三环级联，位置环P控制，带宽分配10:3:1</li><li><strong>资源使用方法：</strong> 解压后搭建三环仿真，观察位置跟踪性能</li><li><strong>学习建议：</strong> 对照KB模块CT-14(三环级联PID)的带宽分配法则</li></ul><h3 id="站6-mtpa专题" tabindex="-1">站6: MTPA专题 <a class="header-anchor" href="#站6-mtpa专题" aria-label="Permalink to &quot;站6: MTPA专题&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 最大转矩电流比原理，id/is最优轨迹推导，内置式PMSM的凸极效应利用</li><li><strong>资源使用方法：</strong> 解压后对照理论推导运行仿真</li><li><strong>学习建议：</strong> MTPA仅对内置式PMSM(Ld≠Lq)有效，表贴式PMSM退化为id=0控制</li></ul><h3 id="站7-mtpa-弱磁综合策略" tabindex="-1">站7: MTPA+弱磁综合策略 <a class="header-anchor" href="#站7-mtpa-弱磁综合策略" aria-label="Permalink to &quot;站7: MTPA+弱磁综合策略&quot;">​</a></h3><ul><li><strong>核心要点：</strong> MTPA+弱磁多方法实现、模糊PI在MTPA+弱磁中的综合应用、全速域控制策略</li><li><strong>资源使用方法：</strong> 先解压第5部分理解多种弱磁方法，再解压第6部分看模糊PI综合应用</li><li><strong>学习建议：</strong> 站7的模糊PI是站4模糊PI的进阶应用——站4是模糊PI替代传统PI，站7是模糊PI在MTPA+弱磁综合策略中的角色</li></ul><h2 id="_5-路径间关联" tabindex="-1">5. 路径间关联 <a class="header-anchor" href="#_5-路径间关联" aria-label="Permalink to &quot;5. 路径间关联&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关联路径</th><th>关系</th><th>说明</th></tr></thead><tbody><tr><td>路径11(FOC仿真到固件)</td><td>前置</td><td>学完站11-5后可开始本路径</td></tr><tr><td>路径13(无位置传感器控制)</td><td>后续</td><td>学完站3后可开始路径13</td></tr><tr><td>路径14(工程实现)</td><td>后续</td><td>本路径的仿真策略可在路径14中落地</td></tr><tr><td>路径9(C仿真)</td><td>替代</td><td>无MATLAB许可证时可用C仿真验证</td></tr></tbody></table><h2 id="_6-补充资源" tabindex="-1">6. 补充资源 <a class="header-anchor" href="#_6-补充资源" aria-label="Permalink to &quot;6. 补充资源&quot;">​</a></h2><ul><li>📂 <code>PMSM_DTC.slx</code> — DTC直接转矩控制（与站1的FOC控制形成对比）</li><li>📂 <code>Parameters_DTC.m</code> — DTC参数配置脚本</li><li>📂 <code>教材1: 袁雷《现代永磁同步电机控制原理》</code></li><li>📂 <code>教材2: 袁登科《永磁同步电动机变频调速系统及其控制》</code></li></ul><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to &quot;7. 常见问题&quot;">​</a></h2><p><strong>Q: zip解压密码是什么？</strong> A: 所有zip压缩包的解压密码统一为 <code>chenshamotor</code>。</p><p><strong>Q: 站4和站7都涉及模糊PI，有什么区别？</strong> A: 站4是模糊PI在双闭环中的应用（用模糊推理替代传统PI整定），站7是模糊PI在MTPA+弱磁综合策略中的应用（PI仅是其中一环，模糊推理用于协调MTPA和弱磁的切换）。站7是站4的进阶。</p><p><strong>Q: 没有MATLAB许可证怎么办？</strong> A: 可使用知识库<a href="./../simulation/SIM-00-C-Simulation-Overview.html">路径9: C仿真验证</a>的C仿真平台替代。</p><p><strong>Q: 教材如何使用？</strong> A: 袁雷的书偏重控制原理推导，袁登科的书偏重系统实现，建议根据需要选读对应章节，不必通读。</p><p>⚠️ <strong>注意事项：</strong> 所有zip压缩包解压密码为 <code>chenshamotor</code>。资源为中文。资源位置可能变化，请以实际路径为准。</p>',27))])}const g=r(n,[["render",s]]);export{m as __pageData,g as default};
